"""Końcowy raport zachowuje wyniki negatywne i obie kontrole normy."""
import json,shutil
from datetime import datetime
from zoneinfo import ZoneInfo
import numpy as np
import raport
from dane import HERE,load,js,sha

def read(p):return json.loads((HERE/p).read_text(encoding='utf-8'))
def interval(x,scale=1):return f'[{float(x[0])*scale:+.5f}, {float(x[1])*scale:+.5f}]'

def main():
    raport.main()  # Recreates figures, bootstrap summaries, no fitting or forwards.
    rows,t=load();p=read('POMIAR.json');f=read('IDENTYFIKACJA.json');d=read('DETEKCJA.json');c=read('DETEKCJA_FC2.json');s=read('SHAM_PODSUMOWANIE.json');b=read('TLO_TEST_PODSUMOWANIE.json');a=read('MAKROWEKTORY.json');x=read('PRZYKLADY_OPIS.json');k=read('KONTROLE_SELEKTYWNOSCI.json');sh=read('SHAM_DIAGNOSTYKA_heldout.json');angles=read('KATY.json')
    now=datetime.now(ZoneInfo('Europe/Warsaw')).isoformat();v=f['presence']['test']['film_weighted'];ci=f['presence']['test']['film_bootstrap95'];base=d['summary']['nohook'];identity=d['summary']['identity'];held=s['heldout'];U=dict(np.load(HERE/'PODPRZESTRZEN.npz'));lda=U['lda_direction'];ldaorder=np.argsort(np.abs(lda))[::-1][:10]
